// Peacock — hand every player The Settler's Almanac on their first join.
// The book itself is pack/patchouli_books/peacock_almanac/ (generated by tools/gen-almanac.py).
// Geolosys gives its own Field Manual the same way (geolosys-common.toml: giveManual = true).

// KubeJS loads every server script into one shared scope; a bare `{}` block does not isolate `const` in
// its Rhino ("redeclaration of var"), so the body lives in a function scope.
;(() => {
PlayerEvents.loggedIn(event => {
  const player = event.player
  if (player.persistentData.getBoolean('peacock_almanac_given')) return
  player.give(Item.of('patchouli:guide_book', '{"patchouli:book":"patchouli:peacock_almanac"}'))
  player.persistentData.putBoolean('peacock_almanac_given', true)
  // the one-line welcome in welcome.js mentions the book; no second message here
})
})()
